import React from 'react';
import SearchBar from './SearchBar';

interface HeroBannerProps {
  searchQuery: string;
  onSearchChange: (query: string) => void;
  onSearchSubmit?: (e: React.FormEvent) => void;
}

const HeroBanner: React.FC<HeroBannerProps> = ({ searchQuery, onSearchChange, onSearchSubmit }) => {
  return (
    <div className="relative w-screen h-screen min-h-screen flex items-end justify-center overflow-hidden pb-20">
      {/* Background Video */}
      <div className="absolute inset-0 w-full h-full overflow-hidden">
        <video
          autoPlay
          loop
          muted
          playsInline
          preload="auto"
          poster="/herobanner.png"
          className="absolute top-0 left-0 w-full h-full object-cover"
        >
          <source src="/herobanner.mp4" type="video/mp4" />
          Your browser does not support the video tag.
        </video>
        {/* Dark overlay for text readability */}
        <div className="absolute inset-0 bg-black/40 z-10"></div>
      </div>

      <div className="max-w-7xl mx-auto text-center px-4 relative z-10 w-full">
        <div className="animate-fade-in-up" style={{ animationDelay: '0.2s' }}>
          <h1 className="text-3xl md:text-5xl font-bold mb-4 leading-tight text-white drop-shadow-2xl font-['Pacifico']"
            style={{ textShadow: '0 4px 20px rgba(0,0,0,0.8), 0 2px 8px rgba(0,0,0,0.6)' }}>
            Taste the <span className="text-orange-500">Magic</span>
          </h1>
          <p className="text-lg md:text-xl mb-8 max-w-2xl mx-auto text-gray-200 font-light"
            style={{ textShadow: '0 2px 12px rgba(0,0,0,0.8), 0 1px 4px rgba(0,0,0,0.6)' }}>
            Your favorite meals, delivered in minutes.
          </p>

          <SearchBar
            value={searchQuery}
            onChange={onSearchChange}
            onSubmit={onSearchSubmit}
            searchButton={true}
            placeholder="Search for restaurants, cuisines..."
            className="w-full bg-white/95 backdrop-blur-sm text-black placeholder-gray-500 border border-white/20 rounded-full px-4 pr-32 py-3 text-lg shadow-xl focus:outline-none focus:ring-2 focus:ring-orange-500 focus:border-orange-500 transition"
          />


          <div className="mt-8 flex flex-wrap justify-center gap-3">
            {['Italian', 'Chinese', 'Indian', 'Mexican', 'Sushi', 'Pizza'].map((cuisine) => (
              <button
                key={cuisine}
                onClick={() => onSearchChange(cuisine)}
                className="px-4 py-2 bg-black/30 hover:bg-black/50 backdrop-blur-md rounded-full text-sm font-medium transition-all duration-300 hover:scale-105 border border-white/20 text-white"
              >
                {cuisine}
              </button>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default HeroBanner;
